import React from 'react';

import { getInputDate } from '@helpers/dateHelper';
import Breadcrumb from '@ui-kit/Breadcrumb';
import PohCheckbox from '@ui-kit/Checkbox';
import PohInput, { InputTypes } from '@ui-kit/Input';
import InputSizes from '@ui-kit/Input/InputSizes';
import PohContainer from '@ui-kit/layout/Container';
import PageLoader from '@ui-kit/Loader';

import { getProductsForPrint } from './productsForPrint.helper';
import { getHikingDataAsync } from '../../../../../@services/hiking.service';
import { getHikingMenuProductsAsync } from '../../../../../@services/hikingMenu.service';
import { IHikingData } from '../../../../../@types/hiking.types';
import { IHikingMenuExtendedProduct } from '../../../../../@types/hikingMenu.types';
import ProductsMatrix from '../ProductsMatrix';

interface IHikingMenuMatrixPageProps {
  id_hiking: number;
}

const HikingMenuMatrixPage: React.FC<IHikingMenuMatrixPageProps> = ({ id_hiking }) => {
  const [hikingData, setHikingData] = React.useState<IHikingData | null>(null);
  const [products, setProducts] = React.useState<IHikingMenuExtendedProduct[]>([]);

  const [date1, setDate1] = React.useState('');
  const [date2, setDate2] = React.useState('');
  const [excludeForce, setExcludeForce] = React.useState(false);
  const [needAssignee, setNeedAssignee] = React.useState(false);

  React.useEffect(() => {
    const init = async () => {
      await getHikingDataAsync(id_hiking).then(setHikingData);
      await getHikingMenuProductsAsync(id_hiking).then(setProducts);
    };

    init().catch();
  }, [id_hiking]);

  if (hikingData == null) {
    return <PageLoader />;
  }

  const productsForPrint = getProductsForPrint(products, hikingData);

  return (
    <PohContainer>
      <Breadcrumb
        data={[
          { href: '/hiking', text: 'Походы' },
          { href: `/hiking/${id_hiking}`, text: hikingData.name },
          { href: `/hiking/${id_hiking}/menu`, text: 'Меню' },
          { href: `/hiking/${id_hiking}/menu/matrix`, text: 'Матрица', active: true },
        ]}
      />
      <h3 className="mb-3">Матрица провизии &laquo;{hikingData.name}&raquo;</h3>
      <aside className="d-flex d-print-none align-items-center" style={{ gap: 12 }}>
        <div>
          <PohInput
            type={InputTypes.datetimeLocal}
            value={date1?.length > 10 ? getInputDate(new Date(date1)) : ''}
            onChange={setDate1}
            size={InputSizes.Small}
          />
        </div>
        <div>
          <PohInput
            type={InputTypes.datetimeLocal}
            value={date2?.length > 10 ? getInputDate(new Date(date2)) : ''}
            onChange={setDate2}
            size={InputSizes.Small}
          />
        </div>
        <div className="text-nowrap">
          {' '}
          <PohCheckbox
            checked={excludeForce}
            onChange={setExcludeForce}
            label="Исключить назначенные"
          />
        </div>
        <div className="text-nowrap">
          <PohCheckbox
            className="text-nowrap"
            checked={needAssignee}
            onChange={setNeedAssignee}
            label="Фотки отвественных по ПП"
          />
        </div>
      </aside>
      <br />
      <div className="overflow-auto">
        <ProductsMatrix
          productsForPrint={productsForPrint}
          dateFrom={new Date(date1)}
          dateTo={new Date(date2)}
          isIncludeAssignee={needAssignee}
          isIncludeForce={!excludeForce}
        />
      </div>
    </PohContainer>
  );
};

export default HikingMenuMatrixPage;
